-- InGameJob public Art and Animation category; Gamesmith remains blocked by public DNS.
alter table public.raven_studio_sources drop constraint if exists raven_studio_sources_provider_check;
alter table public.raven_studio_sources add constraint raven_studio_sources_provider_check
 check(provider in ('pending','ashby','greenhouse','lever','workable','smartrecruiters','bamboohr','icims','avature','jobylon','workwithindies','teamtailor','breezy','recruitee','remotegamejobs','blenderartists','epicforum','artstation','hitmarker','eightbit','skillsearch','gamesjobsdirect','ingamejob'));
insert into public.raven_studio_sources(studio_name,slug,provider,board_key,careers_url,source_kind,segment,segment_note,verification_status,verification_note,priority,enabled,interval_hours,source_verified_at,next_check_at) values
 ('InGameJob Art and Animation','ingamejob-art','ingamejob','ingamejob','https://ingamejob.com/en/jobs/art-and-animation','job_board','unknown','English Art and Animation category only, not whole-board coverage. Actual employers and recruiter client uncertainty retained; remote geographic and work conditions preserved.','verified','Anonymous official category and fresh detail requests verified. Complete bounded pagination, canonical/title/employer and active Apply checks. Serial5second request spacing; at most12 rotating descriptions per check. docs/board-ingamejob-verification.json.',2,true,24,now(),now()),
 ('Gamesmith','gamesmith','pending',null,'https://gamesmith.com/jobs','job_board','unknown','Game-industry job board. Registered but not scanned while public domain DNS fails.','blocked','Public gamesmith.com/www DNS SERVFAIL independently confirmed; anonymous listing/detail unavailable. No speculative adapter or false successful check. docs/board-gamesmith-verification.json.',2,false,24,null,now())
on conflict(slug) do update set studio_name=excluded.studio_name,provider=excluded.provider,board_key=excluded.board_key,careers_url=excluded.careers_url,source_kind=excluded.source_kind,segment=excluded.segment,segment_note=excluded.segment_note,verification_status=excluded.verification_status,verification_note=excluded.verification_note,enabled=excluded.enabled,interval_hours=excluded.interval_hours,source_verified_at=excluded.source_verified_at,next_check_at=excluded.next_check_at,updated_at=now();
